-- Tenth chapter: Kimetsu no Yaiba fanart. Additive; preserves current visibility, accounts, copies and prior claims.
insert into jj_collect.catalog(id,data) values('nu-271','{"id": "nu-271", "number": 271, "name_es": "Mi primera Nichirin", "name_en": "My First Nichirin", "character": "jesus", "theme": "fantasia", "tags": ["kimetsu-no-yaiba"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Cada aventura empieza con algo nuevo; me ilusiona compartir contigo hasta el primer paso.", "dedication_en": "Every adventure starts with something new; I love sharing even the first step with you.", "art": 0, "collection": "decimo-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-272','{"id": "nu-272", "number": 272, "name_es": "La mariposa que elegiste", "name_en": "The Butterfly You Chose", "character": "julisa", "theme": "fantasia", "tags": ["kimetsu-no-yaiba"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Entre tantos detalles de esta historia, quise guardar uno que te hiciera sonreír.", "dedication_en": "Among all the details of this story, I wanted to keep one that would make you smile.", "art": 1, "collection": "decimo-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-273','{"id": "nu-273", "number": 273, "name_es": "Nuestro sendero de glicinas", "name_en": "Our Wisteria Path", "character": "duo", "theme": "fantasia", "tags": ["kimetsu-no-yaiba"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Si el camino se llena de flores, podemos bajar el paso y disfrutarlo juntos.", "dedication_en": "If the path fills with flowers, we can slow down and enjoy it together.", "art": 2, "collection": "decimo-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-274','{"id": "nu-274", "number": 274, "name_es": "Un intento más en la montaña", "name_en": "One More Try on the Mountain", "character": "jesus", "theme": "fantasia", "tags": ["kimetsu-no-yaiba"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Aprender también significa tener paciencia, y me gusta poder contarte mis pequeños avances.", "dedication_en": "Learning also means being patient, and I love telling you about my little progress.", "art": 3, "collection": "decimo-universo"}'::jsonb) on conflict(id) do nothing;
